    assert!(!Path::new(D).exists());let a=read(r("analysis.json"));assert_eq!(a["complete"],true);assert_eq!(a["independent_proof_count"],22498);for(p,h)in read(r("pins.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
